import { ResourceService, hashToken, isEncrypted, notFound, conflict } from '#calm';

// Account deletion ("right to be forgotten").
//
// Order matters, so an interrupted deletion can always be finished later:
//   1. the user is marked { status: 'deleting', deletion: {...} }: from then on they cannot
//      sign in or call the API (privacy/index.js), and the sweep knows to finish the job;
//   2. sessions, devices, password resets and other access are removed;
//   3. owned records are deleted, anonymized or kept, resource by resource;
//   4. extra collections (options.alsoDelete) are cleaned;
//   5. the user record goes last, so until then the 'deleting' mark is still there.
// Every step is safe to run twice: rerunning a half-done deletion only does what is left.

export const BEHAVIORS = ['delete', 'anonymize', 'keep'];
const LEASE_MS = 10 * 60_000; // one purge at a time per user, even with several instances

/**
 * What happens to each resource that has an owner field when its owner is deleted.
 * Precedence: calm.config.js blocks.privacy.resources > resource('x', { onOwnerDelete }) > 'delete'.
 * Personal fields (blanked by 'anonymize'): fields flagged opts.pii, resource option
 * personalFields, and blocks.privacy.personalFields.<resource>.
 */
export function deletionPlan(registry, options) {
  const plan = [];
  for (const entry of registry.values()) {
    const { def } = entry;
    if (!def.ownerField || def.name === 'user') continue;
    const action = options.resources?.[def.name] ?? def.options.onOwnerDelete ?? 'delete';
    const personal = [
      ...new Set([
        ...Object.entries(def.fields).filter(([, field]) => field.opts.pii).map(([key]) => key),
        ...(def.options.personalFields ?? []),
        ...(options.personalFields?.[def.name] ?? []),
      ]),
    ].filter((key) => key !== def.ownerField);
    plan.push({ name: def.name, ownerField: def.ownerField, action, personal, entry, file: entry.files?.resource ?? null });
  }
  return plan;
}

/** Throw at boot for settings that would make a deletion fail or silently keep data. */
export function checkPlan(plan) {
  for (const p of plan) {
    if (!BEHAVIORS.includes(p.action)) throw new Error(`privacy: ${p.name} has onOwnerDelete "${p.action}"; use one of ${BEHAVIORS.join(', ')}`);
    if (p.action === 'anonymize' && p.ownerField === '_id') throw new Error(`privacy: ${p.name} is owned through its _id, so it cannot be anonymized; use 'delete' or 'keep'`);
    const unknown = p.personal.filter((key) => !p.entry.def.fields[key]);
    if (unknown.length) throw new Error(`privacy: personal field(s) ${unknown.join(', ')} do not exist on ${p.name}`);
  }
}

/** Decrypt .encrypted() fields of a raw document (raw driver reads skip the model's hooks). */
export function decrypt(def, doc, cipher) {
  if (!cipher) return doc;
  for (const [key, field] of Object.entries(def.fields)) {
    if (field.opts.encrypted && isEncrypted(doc[key])) doc[key] = cipher.decrypt(doc[key]);
  }
  return doc;
}

/** Owner values are stored as ObjectIds, but imported data sometimes holds the string form. */
export const ownedBy = (ownerField, oid) => ({ [ownerField]: { $in: [oid, String(oid)] } });

// A service that keeps the default no-op hooks can be cleaned with one deleteMany. Services
// with hooks (e.g. file.service.js removing the stored file) get one call per record.
const hasDeleteHooks = (service) =>
  service.beforeDelete !== ResourceService.prototype.beforeDelete || service.afterDelete !== ResourceService.prototype.afterDelete;

export function createEraser(calm, options) {
  const { app } = calm;
  const userEntry = () => app.registry.get('user');
  const users = () => userEntry().model.collection;
  const toId = (id) => new calm.mongoose.Types.ObjectId(String(id));

  /** Remove every way in: sessions, reset links, push devices, 2FA challenges, lockout counters. */
  async function revokeAccess(user) {
    const auth = app.auth?.service;
    const jobs = [
      auth?.Session.deleteMany({ user: user._id }),
      auth?.PasswordReset.deleteMany({ user: user._id }),
      app.push.devices?.deleteMany({ user: user._id }),
      calm.mongoose.models.calmMfaChallenge?.deleteMany({ user: user._id }),
    ];
    if (auth && typeof user.email === 'string') jobs.push(auth.LoginAttempt.deleteOne({ _id: hashToken(`login:${user.email.toLowerCase()}`) }));
    await Promise.all(jobs.filter(Boolean));
  }

  async function eraseResource(p, oid, ctx) {
    const { def, model, service } = p.entry;
    const where = ownedBy(p.ownerField, oid);
    // Raw collection calls: they also reach records hidden by query middleware (soft-deleted
    // ones are still personal data) and are not blocked by .immutable() on personal fields.
    if (p.action === 'keep') return { kept: await model.collection.countDocuments(where) };
    if (p.action === 'anonymize') {
      const $unset = Object.fromEntries([p.ownerField, ...p.personal].map((key) => [key, '']));
      const update = def.timestamps ? { $unset, $set: { updatedAt: new Date() } } : { $unset };
      const res = await model.collection.updateMany(where, update);
      return { anonymized: res.modifiedCount };
    }
    if (!hasDeleteHooks(service)) return { deleted: (await model.collection.deleteMany(where)).deletedCount };

    let deleted = 0;
    const cursor = model.collection.find(where).batchSize(options.batchSize);
    try {
      for await (const raw of cursor) {
        const doc = decrypt(def, raw, app.cipher);
        await service.beforeDelete(doc, ctx);
        deleted += (await model.collection.deleteOne({ _id: doc._id })).deletedCount;
        await service.afterDelete(doc, ctx);
      }
    } finally {
      await cursor.close();
    }
    return { deleted };
  }

  /**
   * Finish the deletion of one user marked 'deleting' whose date has come. Returns the
   * per-resource counts, or null when there was nothing to do (already gone, not due yet,
   * or another process is on it).
   */
  async function purge(userId) {
    const now = new Date();
    const _id = toId(userId);
    const user = await users().findOneAndUpdate(
      { _id, status: 'deleting', 'deletion.scheduledFor': { $lte: now }, 'deletion.lockedUntil': { $not: { $gt: now } } },
      { $set: { 'deletion.lockedUntil': new Date(now.getTime() + LEASE_MS) } },
      { returnDocument: 'after' },
    );
    if (!user) return null;

    const by = user.deletion?.by ?? 'self';
    const ctx = { system: true, user: null, privacy: { userId: String(_id), by } };
    await revokeAccess(user);

    const counts = {};
    for (const p of deletionPlan(app.registry, options)) counts[p.name] = await eraseResource(p, _id, ctx);
    for (const [collection, field] of Object.entries(options.alsoDelete ?? {})) {
      if (!field) continue;
      const res = await calm.mongoose.connection.db.collection(collection).deleteMany(ownedBy(field, _id));
      counts[collection] = { deleted: res.deletedCount };
    }

    // The user record last. Its service hooks run (an avatar file to remove...), but no
    // user.deleted event: audit-log would copy the erased profile into the audit trail.
    const { def, service } = userEntry();
    const passwordFields = Object.entries(def.fields).filter(([, field]) => field.type === 'password').map(([key]) => key);
    const doc = decrypt(def, Object.fromEntries(Object.entries(user).filter(([key]) => !passwordFields.includes(key))), app.cipher);
    await service.beforeDelete(doc, ctx);
    await users().deleteOne({ _id });
    await service.afterDelete(doc, ctx);
    await revokeAccess(user); // a reset link requested while this ran

    calm.events.emit('privacy.account_deleted', { userId: String(_id), by, resources: counts });
    calm.log.info('privacy: account deleted', { userId: String(_id), by });
    return counts;
  }

  /**
   * Start deleting an account: mark it, cut access, then purge now or after the grace period.
   * Resolves to { status: 'deleted' } or { status: 'scheduled', scheduledFor }.
   */
  async function request(userId, { by = 'self', adminId = null, immediate = false } = {}) {
    const _id = toId(userId);
    const user = await users().findOne({ _id });
    if (!user) throw notFound('User not found');
    const now = new Date();
    const graceMs = immediate ? 0 : Math.max(0, Number(options.graceDays) || 0) * 86_400_000;
    const scheduledFor = new Date(now.getTime() + graceMs);

    if (user.status !== 'deleting') {
      await users().updateOne(
        { _id, status: { $ne: 'deleting' } },
        { $set: { status: 'deleting', deletion: { requestedAt: now, scheduledFor, by, previousStatus: user.status ?? null } } },
      );
      calm.events.emit('privacy.deletion_requested', { userId: String(_id), by, adminId, scheduledFor });
    } else if (scheduledFor < (user.deletion?.scheduledFor ?? now)) {
      // Asked again: only ever bring the date forward (an admin deleting right away).
      await users().updateOne({ _id }, { $set: { 'deletion.scheduledFor': scheduledFor } });
    }
    await revokeAccess(user);

    const due = (await users().findOne({ _id }, { projection: { deletion: 1 } }))?.deletion?.scheduledFor ?? now;
    if (due > now) return { status: 'scheduled', scheduledFor: due };
    const counts = await purge(_id);
    return counts ? { status: 'deleted', resources: counts } : { status: 'deleting' };
  }

  /** Undo a scheduled deletion (grace period). Sessions and devices removed meanwhile stay removed. */
  async function cancel(userId) {
    const _id = toId(userId);
    const user = await users().findOne({ _id }, { projection: { status: 1, deletion: 1 } });
    if (!user || user.status !== 'deleting') throw notFound('No deletion is pending for this user');
    const previous = user.deletion?.previousStatus;
    const res = await users().updateOne(
      { _id, status: 'deleting', 'deletion.lockedUntil': { $not: { $gt: new Date() } } },
      previous == null ? { $unset: { status: '', deletion: '' } } : { $set: { status: previous }, $unset: { deletion: '' } },
    );
    if (!res.modifiedCount) throw conflict('The deletion is already running');
    calm.events.emit('privacy.deletion_cancelled', { userId: String(_id) });
  }

  /** Finish due and interrupted deletions. Runs on an interval; safe on several instances. */
  async function sweep({ limit = 100 } = {}) {
    if (!userEntry()) return 0;
    const due = await users()
      .find({ status: 'deleting', 'deletion.scheduledFor': { $lte: new Date() } }, { projection: { _id: 1 } })
      .limit(limit)
      .toArray();
    let done = 0;
    for (const { _id } of due) {
      try {
        if (await purge(_id)) done += 1;
      } catch (err) {
        calm.log.error('privacy: deletion failed, the next sweep retries it', { err, userId: String(_id) });
      }
    }
    return done;
  }

  return { request, purge, cancel, sweep, revokeAccess };
}

import { serialize, maskToken } from '#calm';
import { decrypt, ownedBy } from './erase.js';

// Data export ("right to data portability"): one JSON file with everything a user owns.
//
// Records are read with one cursor per resource and written to the response as they come,
// so a large account never sits in memory. Each record goes through serialize() exactly as
// its owner would see it in the API: hidden and write-only fields and password hashes are
// never written, visibleTo() rules apply, encrypted fields are decrypted only where the
// owner is allowed to see them. The manifest is written last so its counts match the file.

const FORMAT = 'calmapi-export/1';

const pretty = (value, indent) => JSON.stringify(value, null, 2).replace(/\n/g, `\n${' '.repeat(indent)}`);

/** <app>-export-<date>.json, safe inside a quoted Content-Disposition filename. */
export function exportFilename(appName, date = new Date()) {
  const slug = String(appName).toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'app';
  return `${slug}-export-${date.toISOString().slice(0, 10)}.json`;
}

/** Write respecting backpressure; fail fast when the client went away. */
function writer(res) {
  return (text) => {
    if (res.destroyed) return Promise.reject(new Error('The client disconnected during the export'));
    if (res.write(text)) return Promise.resolve();
    return new Promise((resolve, reject) => {
      const done = (err) => {
        res.off('drain', onDrain);
        res.off('close', onClose);
        if (err) reject(err);
        else resolve();
      };
      const onDrain = () => done();
      const onClose = () => done(new Error('The client disconnected during the export'));
      res.once('drain', onDrain);
      res.once('close', onClose);
    });
  };
}

/**
 * Stream the export of `userId` to an Express response.
 * Resolves to the counts written ({ profile: 1, note: 3, sessions: 2, devices: 1 }).
 */
export async function streamExport(res, { app, userId, resources, batchSize }) {
  const User = app.model('user');
  const userDef = app.registry.get('user').def;
  const raw = await User.collection.findOne({ _id: new app.mongoose.Types.ObjectId(String(userId)) });
  if (!raw) return null;
  // Like req.user: fields the model never selects (hidden, write-only, password hashes) are dropped.
  for (const [key, field] of Object.entries(userDef.fields)) if (!field.isOutput) delete raw[key];
  const profileDoc = decrypt(userDef, raw, app.cipher);
  // The viewer is the data subject: owner rules pass, their own roles apply.
  const viewer = { ...profileDoc, id: String(profileDoc._id) };
  const generatedAt = new Date();
  const counts = { profile: 1 };
  const profile = await serialize(userDef, profileDoc, { user: viewer, registry: app.registry });

  res.status(200);
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  res.setHeader('Content-Disposition', `attachment; filename="${exportFilename(app.config.app.name, generatedAt)}"`);
  res.setHeader('Cache-Control', 'no-store');
  const write = writer(res);
  await write(
    `{\n  "format": ${JSON.stringify(FORMAT)},\n  "app": ${JSON.stringify(app.config.app.name)},\n  "userId": ${JSON.stringify(viewer.id)},\n` +
      `  "generatedAt": ${JSON.stringify(generatedAt)},\n  "profile": ${pretty(profile, 2)},\n  "resources": {`,
  );

  for (const [i, p] of resources.entries()) {
    const { def, model } = p.entry;
    await write(`${i ? ',' : ''}\n    ${JSON.stringify(p.name)}: [`);
    let n = 0;
    let chunk = '';
    const cursor = model.collection.find(ownedBy(p.ownerField, profileDoc._id)).sort({ _id: 1 }).batchSize(batchSize);
    try {
      for await (const doc of cursor) {
        const out = await serialize(def, decrypt(def, doc, app.cipher), { user: viewer, registry: app.registry });
        chunk += `${n ? ',' : ''}\n      ${pretty(out, 6)}`;
        n += 1;
        if (n % batchSize === 0) {
          await write(chunk);
          chunk = '';
        }
      }
    } finally {
      await cursor.close();
    }
    await write(`${chunk}${n ? '\n    ' : ''}]`);
    counts[p.name] = n;
  }

  // Sessions without their token hashes, devices with masked push tokens.
  const sessions = app.auth
    ? (await app.auth.service.Session.find({ user: profileDoc._id }).sort({ createdAt: 1 }).lean()).map((s) => ({
        id: String(s._id),
        createdAt: s.createdAt,
        lastUsedAt: s.lastUsedAt ?? null,
        expiresAt: s.expiresAt,
        ip: s.ip ?? null,
        userAgent: s.userAgent ?? null,
      }))
    : [];
  const devices = app.push.devices
    ? (await app.push.devices.find({ user: profileDoc._id }).sort({ createdAt: 1 }).lean()).map((d) => ({
        id: String(d._id),
        platform: d.platform,
        name: d.name ?? null,
        appVersion: d.appVersion ?? null,
        locale: d.locale ?? null,
        token: maskToken(d.token),
        lastSeenAt: d.lastSeenAt ?? null,
        createdAt: d.createdAt,
      }))
    : [];
  counts.sessions = sessions.length;
  counts.devices = devices.length;

  const manifest = {
    format: FORMAT,
    generatedAt,
    userId: viewer.id,
    resources: resources.map((p) => p.name),
    counts,
    note: 'Records you own, as the API shows them to you. Hidden fields, password hashes and session tokens are never exported.',
  };
  await write(`${resources.length ? '\n  ' : ''}},\n  "sessions": ${pretty(sessions, 2)},\n  "devices": ${pretty(devices, 2)},\n  "manifest": ${pretty(manifest, 2)}\n}\n`);
  res.end();
  return counts;
}

import { definePlugin, f, forbidden, unauthorized, notFound, validationError, verifyPassword } from '#calm';
import { createEraser, deletionPlan, checkPlan } from './erase.js';
import { streamExport } from './export.js';

// Privacy: data export (GDPR art. 20, portability) and account deletion (art. 17, erasure).
//
//   GET    /api/auth/me/export                      your data as a JSON download
//   DELETE /api/auth/me              { password }   delete your account and your data
//   POST   /api/admin/users/:id/export              admins, for support requests
//   DELETE /api/admin/users/:id      { immediate? } admins, for support requests
//   POST   /api/admin/users/:id/cancel-deletion     admins, during the grace period
//
// What happens to each resource is decided per resource (default 'delete'):
//   resource('post', { onOwnerDelete: 'anonymize', personalFields: ['authorName'], fields })
// or centrally in calm.config.js: blocks: { privacy: { resources: { post: 'keep' } } }.
// `calm doctor` lists the plan and warns about resources that keep data.

const isId = (s) => typeof s === 'string' && /^[a-f\d]{24}$/i.test(s);

export default definePlugin({
  name: 'privacy',
  options: {
    graceDays: 0, // > 0: the account is locked at once and erased this many days later
    sweepEveryMinutes: 60, // how often scheduled and interrupted deletions are finished; 0 = never
    resources: {}, // { post: 'delete' | 'anonymize' | 'keep' }, overrides onOwnerDelete
    personalFields: {}, // { post: ['authorName'] }, blanked when a record is anonymized
    alsoDelete: { calm_idempotency: 'user' }, // other collections to clean: { collection: userIdField }
    exportLimit: { windowMs: 60 * 60_000, max: 5 }, // exports per user (needs config.rateLimit.enabled); false = no limit
    batchSize: 200,
    cascadeCrudDelete: true, // DELETE /api/users/:id (user CRUD) erases the same way
  },
  setup(calm, options) {
    const eraser = createEraser(calm, options);
    calm.provide('privacy', { ...eraser, plan: () => deletionPlan(calm.app.registry, options) });

    calm.onResource((def) => {
      if (def.name !== 'user') return def;
      // Present while an account is being deleted: { requestedAt, scheduledFor, by, previousStatus, lockedUntil }.
      def.fields.deletion = f.json().hidden();
      return def;
    });

    // Every way an account can be deleted goes through the same erasure.
    calm.onService(({ def, service }) => {
      if (def.name !== 'user' || !options.cascadeCrudDelete) return;
      service.remove = async (id, ctx = {}) => {
        const doc = await service.findOne({ _id: id }, ctx);
        if (!doc) throw notFound('user not found');
        const self = ctx.user && String(ctx.user.id) === String(doc._id);
        await eraser.request(doc._id, { by: !ctx.user ? 'system' : self ? 'self' : 'admin', adminId: self ? null : (ctx.user?.id ?? null), immediate: true });
        return doc;
      };
    });

    // A user marked 'deleting' is out: no new session, and no request with any credential
    // (sessions are revoked anyway; this covers API keys and other authenticators).
    calm.loginChallenge((user) => {
      if (user.status === 'deleting') throw forbidden('This account is being deleted');
      return null;
    });
    calm.guard((ctx) => {
      if (ctx.user?.status === 'deleting') throw unauthorized('This account is being deleted');
    });

    async function exportTo(ctx, userId, meta) {
      const resources = deletionPlan(calm.app.registry, options);
      let counts;
      try {
        counts = await streamExport(ctx.res, { app: calm.app, userId, resources, batchSize: options.batchSize });
      } catch (err) {
        if (!ctx.res.headersSent) {
          ctx.res.removeHeader('Content-Disposition');
          throw err;
        }
        // Half a file must not look like a whole one: cut the connection so the download fails.
        if (ctx.res.destroyed) calm.log.info('privacy: export cancelled by the client', { userId: String(userId) });
        else calm.log.error('privacy: export failed midway', { err, userId: String(userId) });
        ctx.res.destroy();
        return;
      }
      if (!counts) throw notFound('User not found');
      calm.events.emit('privacy.exported', { userId: String(userId), ...meta, counts });
    }

    const answer = (ctx, result) =>
      result.status === 'deleted' ? undefined : ctx.reply({ status: result.status, scheduledFor: result.scheduledFor ?? null }, { status: 202 });

    const userId = (ctx) => {
      if (!isId(ctx.params.userId)) throw notFound('User not found');
      return ctx.params.userId;
    };

    calm.routes((r) => {
      if (!calm.app.auth) {
        calm.log.warn('privacy: auth is off, so the export and delete routes are not registered');
        return;
      }
      checkPlan(deletionPlan(calm.app.registry, options));
      const userDef = calm.app.registry.get('user').def;
      const passwordField = Object.entries(userDef.fields).find(([, field]) => field.type === 'password')?.[0];
      const limit = options.exportLimit ? { ...options.exportLimit, key: (req) => `user:${req.user?.id ?? req.ip}` } : null;
      const tags = ['privacy'];

      r.get('/auth/me/export', { policy: 'authenticated', summary: 'Download everything you own (JSON file)', rateLimit: limit, tags }, (ctx) =>
        exportTo(ctx, ctx.user.id, { by: 'self' }),
      );

      r.delete(
        '/auth/me',
        {
          policy: 'authenticated',
          summary: 'Delete your account and your data (confirm with your password)',
          description: `204 when deleted, 202 when scheduled (grace period of ${options.graceDays} days).`,
          rateLimit: 'auth',
          input: { password: f.string().required().max(128) },
          tags,
        },
        async (ctx) => {
          const user = await calm.app.model('user').findById(ctx.user._id).select(`+${passwordField}`).lean();
          if (!(await verifyPassword(ctx.body.password, user?.[passwordField]))) {
            calm.events.emit('security.account_delete_failed', { userId: ctx.user.id, ip: ctx.req.ip });
            throw validationError({ password: 'Password is incorrect' });
          }
          return answer(ctx, await eraser.request(ctx.user._id, { by: 'self' }));
        },
      );

      r.post('/admin/users/:userId/export', { policy: 'admin', summary: "Download a user's data (support request)", tags }, (ctx) =>
        exportTo(ctx, userId(ctx), { by: 'admin', adminId: ctx.user.id }),
      );

      r.delete(
        '/admin/users/:userId',
        { policy: 'admin', summary: 'Delete an account and its data (support request)', input: { immediate: f.boolean() }, tags },
        async (ctx) => answer(ctx, await eraser.request(userId(ctx), { by: 'admin', adminId: ctx.user.id, immediate: ctx.body.immediate === true })),
      );

      r.post('/admin/users/:userId/cancel-deletion', { policy: 'admin', summary: 'Cancel a scheduled account deletion', tags }, async (ctx) => {
        await eraser.cancel(userId(ctx));
      });
    });

    let timer = null;
    calm.onStart(() => {
      const minutes = Number(options.sweepEveryMinutes);
      if (!minutes) return;
      timer = setInterval(() => eraser.sweep().catch((err) => calm.log.error('privacy: sweep failed', { err })), minutes * 60_000);
      timer.unref();
    });
    calm.onShutdown(() => clearInterval(timer));

    calm.doctor((app) => {
      if (!app.auth) return [{ level: 'warn', id: 'privacy-no-auth', title: 'privacy: auth is off', detail: 'The export and delete routes need auth and a user resource.' }];
      const plan = deletionPlan(app.registry, options);
      const findings = [];
      const what = (p) =>
        p.action === 'delete'
          ? `${p.name} deleted`
          : p.action === 'anonymize'
            ? `${p.name} kept without owner (${[p.ownerField, ...p.personal].join(', ')} removed)`
            : `${p.name} kept as is`;
      const extra = Object.entries(options.alsoDelete ?? {}).filter(([, field]) => field).map(([c, field]) => `${c} (by ${field})`);
      const grace = Number(options.graceDays) > 0 ? `${options.graceDays} days (the account is locked meanwhile)` : 'none, data is erased right away';
      findings.push({
        level: 'info',
        id: 'privacy-plan',
        title: 'What deleting an account does',
        detail:
          `Owned records: ${plan.length ? plan.map(what).join('; ') : 'no resource has an owner field'}. ` +
          `Always deleted: the profile, sessions, push devices, password reset links${extra.length ? `, ${extra.join(', ')}` : ''}. Grace period: ${grace}.`,
      });
      for (const p of plan.filter((x) => x.action === 'keep')) {
        findings.push({
          level: 'warn',
          id: `privacy-keep-${p.name}`,
          title: `${p.name}: records stay when their owner deletes their account`,
          detail: `onOwnerDelete is 'keep', so ${p.name}.${p.ownerField} keeps the deleted account's id and any personal data in these records stays. Prefer 'anonymize' (with personalFields) or 'delete' unless you must keep them (invoices...), and say so in your privacy policy.`,
          file: p.file,
        });
      }
      const unknown = Object.keys(options.resources ?? {}).filter((name) => !plan.some((p) => p.name === name));
      if (unknown.length) findings.push({ level: 'warn', id: 'privacy-unknown-resource', title: `privacy: blocks.privacy.resources names ${unknown.join(', ')}`, detail: 'No resource with an owner field has that name. Check the spelling.' });
      const refs = [];
      for (const { def } of app.registry.values()) {
        for (const [key, field] of Object.entries(def.fields)) {
          const target = field.type === 'ref' ? field.opts.ref : field.type === 'array' && field.opts.of.type === 'ref' ? field.opts.of.opts.ref : null;
          if (target === 'user' && key !== def.ownerField) refs.push(`${def.name}.${key}`);
        }
      }
      if (refs.length) findings.push({ level: 'info', id: 'privacy-user-refs', title: 'User references that are not owner fields', detail: `${refs.join(', ')} keep pointing at deleted accounts (the records are not the user's, so they are not erased).` });
      return findings;
    });
  },
});
